-- Redline (BeamMP Server Manager) helper plugin.
-- Auto-generated by Redline (BeamMP Server Manager); it is overwritten every time the server starts.
-- * Blocks vehicles you switched off in the manager (blocked.lua)
-- * Writes the player list to status.json so the manager can show who is online

local DIR = "Resources/Server/BeamMPManager/"
local blocked = {}

local function loadBlocked()
  local chunk = loadfile(DIR .. "blocked.lua")
  if chunk then
    local ok, t = pcall(chunk)
    if ok and type(t) == "table" then blocked = t end
  end
end

local function modelOf(data)
  if type(data) ~= "string" then return nil end
  return data:match('"jbm"%s*:%s*"([^"]+)"')
end

local function check(pid, data)
  loadBlocked()
  local m = modelOf(data)
  if m and blocked[m] then
    MP.SendChatMessage(pid, "The vehicle '" .. m .. "' is disabled on this server.")
    return 1
  end
  return 0
end

function mgrOnSpawn(pid, vid, data) return check(pid, data) end
function mgrOnEdit(pid, vid, data) return check(pid, data) end

local function esc(s)
  return (tostring(s):gsub('[%c"\\]', function(c) return string.format("\\u%04x", c:byte()) end))
end

function mgrTick()
  local players = MP.GetPlayers() or {}
  local parts = {}
  for id, name in pairs(players) do
    local n = 0
    local vehs = MP.GetPlayerVehicles(id)
    if type(vehs) == "table" then for _ in pairs(vehs) do n = n + 1 end end
    local guest = false
    if MP.IsPlayerGuest then guest = MP.IsPlayerGuest(id) and true or false end
    parts[#parts + 1] = string.format('{"id":%d,"name":"%s","vehicles":%d,"guest":%s}', id, esc(name), n, tostring(guest))
  end
  local f = io.open(DIR .. "status.json", "w")
  if f then
    f:write('{"time":' .. os.time() .. ',"players":[' .. table.concat(parts, ",") .. ']}')
    f:close()
  end
end

loadBlocked()
MP.RegisterEvent("onVehicleSpawn", "mgrOnSpawn")
MP.RegisterEvent("onVehicleEdited", "mgrOnEdit")
MP.RegisterEvent("mgrTick", "mgrTick")
MP.CreateEventTimer("mgrTick", 2000)
print("[Redline (BeamMP Server Manager)] helper plugin loaded")
